/**
 * System tray icon + context menu.
 *
 * Present when settings.general.closeBehavior === 'tray' or the app starts minimized.
 * The icon is bundled through electron-vite's `?asset` import (build/tray.png, generated by
 * scripts/generate-icons.mjs); a missing file degrades to an empty image instead of crashing.
 */
import { app, Menu, nativeImage, Tray, type MenuItemConstructorOptions, type NativeImage } from 'electron'
import { existsSync, readFileSync } from 'node:fs'
import trayIconPath from '../../build/tray.png?asset'
import trayIcon2xPath from '../../build/tray@2x.png?asset'
import { log } from './logger'
import { settingsStore } from './settingsStore'
import { setQuitting, setTrayAvailabilityProvider, showMainWindow } from './window'

const TOOLTIP = 'VibeSync'

let tray: Tray | null = null

export function hasTray(): boolean {
  return tray !== null && !tray.isDestroyed()
}

export function getTray(): Tray | null {
  return hasTray() ? tray : null
}

function loadTrayImage(): NativeImage {
  try {
    if (typeof trayIconPath === 'string' && existsSync(trayIconPath)) {
      const img = nativeImage.createFromPath(trayIconPath)
      if (!img.isEmpty()) {
        if (typeof trayIcon2xPath === 'string' && existsSync(trayIcon2xPath)) {
          try {
            img.addRepresentation({ scaleFactor: 2, buffer: readFileSync(trayIcon2xPath) })
          } catch (err) {
            log('debug', 'Could not add the 2x tray icon representation', err)
          }
        }
        return img
      }
    }
  } catch (err) {
    log('warn', 'Could not load the tray icon', err)
  }
  log('warn', 'Tray icon file missing; using an empty icon (run `npm run icons`)')
  return nativeImage.createEmpty()
}

function buildMenu(): Menu {
  const general = settingsStore.get().general
  const template: MenuItemConstructorOptions[] = [
    { label: 'Show VibeSync', click: () => showMainWindow() },
    { type: 'separator' },
    {
      label: 'Always on top',
      type: 'checkbox',
      checked: general.alwaysOnTop,
      click: (item) => settingsStore.set({ general: { alwaysOnTop: item.checked } })
    },
    { type: 'separator' },
    {
      label: 'Quit VibeSync',
      click: () => {
        setQuitting(true)
        app.quit()
      }
    }
  ]
  return Menu.buildFromTemplate(template)
}

/** Create the tray icon (idempotent). Returns null when the platform refuses to create one. */
export function createTray(): Tray | null {
  if (hasTray()) return tray
  try {
    const t = new Tray(loadTrayImage())
    t.setToolTip(TOOLTIP)
    t.setContextMenu(buildMenu())
    t.on('click', () => showMainWindow())
    t.on('double-click', () => showMainWindow())
    tray = t
    setTrayAvailabilityProvider(hasTray)
    log('info', 'Tray icon created')
    return t
  } catch (err) {
    tray = null
    log('error', 'Could not create the tray icon', err)
    return null
  }
}

export function destroyTray(): void {
  if (!tray) return
  try {
    if (!tray.isDestroyed()) tray.destroy()
  } catch (err) {
    log('warn', 'Could not destroy the tray icon', err)
  }
  tray = null
  log('info', 'Tray icon removed')
}

/** Rebuild the context menu so the mode radio / always-on-top checkbox reflect the settings. */
export function refreshTrayMenu(): void {
  const t = getTray()
  if (!t) return
  try {
    t.setContextMenu(buildMenu())
  } catch (err) {
    log('warn', 'Could not refresh the tray menu', err)
  }
}
